/**  Where on a machine a run happens: `windows`, or `wsl:<distro>`. */
export type RunsIn = string;

/**  Who answers a run's steps in ask mode. */
export type StepsBy = 
/**  The machine's owner. */
"owner" | 
/**  Whoever asked. */
"asker";

/**  One tag in a message: `@person` or `@person/place`. */
export type Tag = {
	/**  Whose place. */
	person: PersonName,
	/**  Which place: `machine` for `@person`. */
	place: PlaceName,
};
